import {readdir,readFile,writeFile,mkdir,access} from 'node:fs/promises';import {resolve,relative,extname} from 'node:path';import {load} from 'cheerio';
const root=resolve('site'),out='diagnostics/platform-link-audit-20261114',base='https://hossambahr.com',pages=new Map(),refs=[],issues=[],assets=new Set();await mkdir(out,{recursive:true});
async function walk(dir){for(const e of await readdir(dir,{withFileTypes:true})){if(['.git','node_modules','artifacts','zero-defect-smoke'].includes(e.name))continue;const p=resolve(dir,e.name);if(e.isDirectory())await walk(p);else if(e.name.endsWith('.html')){const rel=relative(root,p).replaceAll('\\','/'),route=rel==='index.html'?'/':rel.endsWith('/index.html')?'/'+rel.slice(0,-10):'/'+rel;pages.set(route,{file:p,html:await readFile(p,'utf8')});}}}await walk(root);
const normal=p=>{p=decodeURIComponent(p);return p.endsWith('/index.html')?p.slice(0,-10):p==='/index.html'?'/':p;};
for(const [route,p] of pages){const $=load(p.html);p.ids=new Set($('[id],a[name]').map((_,e)=>$(e).attr('id')||$(e).attr('name')).get());p.lang=$('html').attr('lang');$('a[href],form[action]').each((_,e)=>{const raw=$(e).attr(e.tagName==='form'?'action':'href'),text=$(e).text().replace(/\s+/g,' ').trim().slice(0,160);if(!raw||/^(mailto:|tel:)/i.test(raw))return;if(/^javascript:/i.test(raw)){issues.push({kind:'JAVASCRIPT_LINK',route,href:raw,text});return;}let u;try{u=new URL(raw,base+route);}catch{issues.push({kind:'INVALID_URL',route,href:raw,text});return;}if(!['hossambahr.com','www.hossambahr.com'].includes(u.hostname))return;refs.push({route,href:raw,path:normal(u.pathname),hash:u.hash?decodeURIComponent(u.hash.slice(1)):'',text,tag:e.tagName});});$('img[src],script[src],link[rel="stylesheet"][href]').each((_,e)=>{const raw=$(e).attr('src')||$(e).attr('href');try{const u=new URL(raw,base+route);if(u.hostname==='hossambahr.com')assets.add(decodeURIComponent(u.pathname));}catch{}});}
async function exists(path){try{await access(resolve(root,'.'+path));return true;}catch{return false;}}
for(const r of refs){const target=pages.get(r.path)||pages.get(r.path+'/')||pages.get(r.path+'.html');if(!target){if(!(await exists(r.path)))issues.push({kind:'MISSING_ROUTE',...r});continue;}if(r.hash&&!target.ids.has(r.hash))issues.push({kind:'MISSING_STATIC_FRAGMENT',...r,targetHasScripts:/<script/i.test(target.html)});if(r.route.startsWith('/en/')&&!r.path.startsWith('/en/')&&r.tag==='a'&&!/Arabic|العربية|^AR$/.test(r.text)&&r.path!=='/')issues.push({kind:'LOCALE_REVIEW',...r});if(r.href==='#')issues.push({kind:'PLACEHOLDER_LINK',...r});}
const missingAssets=[];for(const a of assets)if(!(await exists(a)))missingAssets.push(a);
const live=[],jobs=[...pages.keys()];let cursor=0;await Promise.all(Array.from({length:10},async()=>{while(cursor<jobs.length){const route=jobs[cursor++];let row={route};try{const res=await fetch(base+encodeURI(route)+'?linkAudit=20261114',{signal:AbortSignal.timeout(25000),redirect:'follow'}),html=await res.text(),$=load(html);row={...row,status:res.status,finalURL:res.url,lang:$('html').attr('lang'),title:$('title').text(),main:!!$('main,article').length,canonical:$('link[rel="canonical"]').attr('href')};if(res.status!==200&&!/^\/404/.test(route))issues.push({kind:'LIVE_HTTP_FAILURE',...row});if(!row.title||(!row.main&&!/404/.test(route)))issues.push({kind:'LIVE_EMPTY_CONTENT',...row});}catch(e){row.error=e.message;issues.push({kind:'LIVE_NETWORK_UNVERIFIED',...row});}live.push(row);}}));
const summary={sourceSHA:process.env.SOURCE_SHA,capturedAt:new Date().toISOString(),pages:pages.size,internalReferences:refs.length,assets:assets.size,missingAssets,livePages:live.length,issueCounts:Object.fromEntries([...new Set(issues.map(i=>i.kind))].map(k=>[k,issues.filter(i=>i.kind===k).length]))};await writeFile(out+'/report.json',JSON.stringify({summary,issues,live},null,2));console.log(JSON.stringify(summary));